/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, E, FracField, Mul, PolyRing, Pow, QQ, Rational, Sym, ZZ, add, fn, mul, pow, sfield, symbols, xreplace } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.fields", () => {
  it("((x**2 + y)/(z + 1)).diff(x)", () => {
    const [x, y, z] = symbols('x y z');
    const v1 = new FracField([x, y, z], ZZ, 'lex');
    const v2 = new FracField([x, y, z], ZZ, 'lex');
    expect(sympyStr(v1['new'](v1.ring.fromExpr(add(y, pow(x, Rational.of(2n, 1n, { gcd: 1n })))), v1.ring.fromExpr(add(Rational.of(1n, 1n, { gcd: 1n }), z))).diff(v2['new'](v2.ring.fromExpr(x), v2.ring.fromExpr(Rational.of(1n, 1n, { gcd: 1n })))))).toBe('2*x/(z + 1)');
  });
  it("K", () => {
    const x = new Sym('x');
    expect(sympyStr(at(sfield(mul(pow(x, Rational.of(-5n, 3n, { gcd: 1n })), add(mul(Rational.of(4n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), mul(x, fn('log', [x], { evaluate: false }))), new Pow(E, pow(x, Rational.of(-1n, 1n, { gcd: 1n }))))), 0))).toBe('Rational function field in x, exp(1/x), log(x), x**(1/3) over ZZ with lex order');
  });
  it("f", () => {
    const x = new Sym('x');
    expect(sympyStr(at(sfield(mul(pow(x, Rational.of(-5n, 3n, { gcd: 1n })), add(mul(Rational.of(4n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), mul(x, fn('log', [x], { evaluate: false }))), new Pow(E, pow(x, Rational.of(-1n, 1n, { gcd: 1n }))))), 1))).toBe('(4*x**2*(exp(1/x)) + x*(exp(1/x))*(log(x)))/((x**(1/3))**5)');
  });
});

